+ if(/(dün (günlerden ne|hangi gün)|yesterday)/i.test(t)){const d=new Date(clock.now);d.setDate(d.getDate()-1);return '<h2>Dün</h2><p>'+esc(new Intl.DateTimeFormat('tr-TR',{timeZone:'Europe/Istanbul',weekday:'long',year:'numeric',month:'2-digit',day:'2-digit'}).format(d))+' (Europe/Istanbul)</p>'}
